@spec cmgr_overrides_spec  src=tests/specs/cmgr_overrides_spec.lua  loc=217  cases=10

# Intent
  commandManager binding overrides (step 0): the token codec and the
  persist/reload plumbing behind clickable keybinding customisation.
  Tokens are the stable ASCII on-disk form ('Ctrl+Z'); rebind writes both
  the live keymap and the persisted tokens, loadOverrides reads them back.

# Helpers
  @fn newCommandManager(cm)  @ 9-11
  @fn fakeCm(initial)  @ 35-46
      -- Deep-copy at the boundary mirrors the real configManager contract, so a test
      -- can't accidentally rely on aliasing cm's internal state.
  @fn installFamily(mgr)  @ 51-60
      -- A generated family as manifest.lua declares one: members sharing a family table,
      -- each carrying the unmasked token its declared chord is masked from. The bases
      -- mirror the drop family's -- bare digits, a bare letter, then a Shift+letter.
  @fn chordOf(mgr, name)  @ 63-67
      -- The single chord a family member holds, as (key, mods).

# Cases
  @case 'token codec round-trips bare / modified / multi-mod / keypad / punctuation'  [pure]  @ 71-87
  @case 'specForToken reports unknown key and unknown modifier'  [pure]  @ 91-98
  @case 'rebind updates the live keymap and persists tokens'  [pure]  @ 102-112
  @case 'rebind to an empty list explicitly unbinds and persists the empty array'  [pure]  @ 116-123
  @case 'rebindFamily re-masks every member from its base token'  [pure]  @ 130-145
  @case 'familyVictim is silent when the whole mask is free'  [pure]  @ 151-157
  @case 'familyVictim names the command holding one of the proposed chords'  [pure]  @ 161-170
  @case 'familyVictim catches two members collapsing onto one chord'  [pure]  @ 176-184
  @case 'loadOverrides re-applies persisted tokens onto a fresh manager'  [pure]  @ 188-201
  @case 'loadOverrides skips malformed tokens, keeps the good ones, tolerates unknown scopes'  [pure]  @ 205-215

